<?php

declare(strict_types=1);

if (!defined('_PS_VERSION_')) {
    exit;
}

function upgrade_module_1_0_4($module): bool
{
    // Existing derivatives may have been generated by the old rotation order.
    // Mark the catalogue as pending so they can be safely rebuilt from the
    // untouched originals with the corrected alpha-compositing pipeline.
    return Configuration::updateValue('ABW_CATALOG_DIRTY', 1)
        && Configuration::updateValue('ABW_BATCH_ERRORS', 0);
}
